// validateRequestValue accepts every planned value. An unknown value of a computed attribute is
// left out of the request, and the server supplies it, as the released resource did.
func validateRequestValue(_ path.Path, _, _ attr.Value, _ bool, _ *diag.Diagnostics) {}

var createFields = []struct {
	attr          string
	serverDefault bool
}{
	{attr: "time_frame", serverDefault: false},
	{attr: "annotations", serverDefault: false},
	{attr: "description", serverDefault: false},
	{attr: "auto_refresh", serverDefault: false},
	{attr: "filters", serverDefault: false},
	{attr: "folder", serverDefault: false},
	{attr: "layout", serverDefault: false},
	{attr: "name", serverDefault: false},
	{attr: "variables", serverDefault: false},
	{attr: "variables_v2", serverDefault: false},
}

func validateCreate(ctx context.Context, config, plan tfData) diag.Diagnostics {
	var diags diag.Diagnostics
	for _, field := range createFields {
		var c, p attr.Value
		var fieldDiags diag.Diagnostics
		fieldDiags.Append(config.GetAttribute(ctx, path.Root(field.attr), &c)...)
		fieldDiags.Append(plan.GetAttribute(ctx, path.Root(field.attr), &p)...)
		diags.Append(fieldDiags...)
		if fieldDiags.HasError() {
			continue
		}
		p = requestValue(ctx, field.attr, p, &diags)
		validateRequestValue(path.Root(field.attr), c, p, field.serverDefault, &diags)
	}
	return diags
}

// serverAttrs are the paths of the computed attributes inside the values
// that a request sends, with list and map steps left out. The server sets
// them.
var serverAttrs = map[string]bool{
	"layout.sections.rows.widgets.definition.data_table.query.spans.grouping.aggregations.id": true,
}

// requestValue returns v with a null value for each attribute that the server
// sets. When the resource changes, Terraform plans these attributes as
// unknown. A request does not send them, so a change check and an
// unknown-value check must not see them.
func requestValue(ctx context.Context, at string, v attr.Value, diags *diag.Diagnostics) attr.Value {
	if v == nil || v.IsNull() || v.IsUnknown() {
		return v
	}
	switch v := v.(type) {
	case types.Object:
		attrTypes := v.AttributeTypes(ctx)
		out := make(map[string]attr.Value, len(attrTypes))
		for name, child := range v.Attributes() {
			if serverAttrs[at+"."+name] {
				out[name] = nullValue(ctx, attrTypes[name], diags)
			} else {
				out[name] = requestValue(ctx, at+"."+name, child, diags)
			}
		}
		value, d := types.ObjectValue(attrTypes, out)
		diags.Append(d...)
		return value
	case types.List:
		elems := v.Elements()
		out := make([]attr.Value, len(elems))
		for i, child := range elems {
			out[i] = requestValue(ctx, at, child, diags)
		}
		value, d := types.ListValue(v.ElementType(ctx), out)
		diags.Append(d...)
		return value
	case types.Set:
		elems := v.Elements()
		out := make([]attr.Value, len(elems))
		for i, child := range elems {
			out[i] = requestValue(ctx, at, child, diags)
		}
		value, d := types.SetValue(v.ElementType(ctx), out)
		diags.Append(d...)
		return value
	case types.Map:
		elems := v.Elements()
		out := make(map[string]attr.Value, len(elems))
		for key, child := range elems {
			out[key] = requestValue(ctx, at, child, diags)
		}
		value, d := types.MapValue(v.ElementType(ctx), out)
		diags.Append(d...)
		return value
	}
	return v
}

// nullValue returns the null value of type t.
func nullValue(ctx context.Context, t attr.Type, diags *diag.Diagnostics) attr.Value {
	value, err := t.ValueFromTerraform(ctx, tftypes.NewValue(t.TerraformType(ctx), nil))
	if err != nil {
		diags.AddError("Invalid value", err.Error())
	}
	return value
}

// expandCreate returns the Create request body. A null value is not sent.
func expandCreate(ctx context.Context, m *DashboardModel) (*dashboard_service.CreateDashboardRequestDataStructure, diag.Diagnostics) {
	var diags diag.Diagnostics
	out := expandDashboardCreate(ctx, path.Empty(), m, &diags)
	return &dashboard_service.CreateDashboardRequestDataStructure{Dashboard: valueOf(out)}, diags
}

// expandUpdate returns the Update request body with every Update field. A
// null value is not sent, and the server clears it (a full replace).
func expandUpdate(ctx context.Context, m *DashboardModel) (*dashboard_service.ReplaceDashboardRequestDataStructure, diag.Diagnostics) {
	var diags diag.Diagnostics
	out := expandDashboardUpdate(ctx, path.Empty(), m, &diags)
	return &dashboard_service.ReplaceDashboardRequestDataStructure{Dashboard: out}, diags
}

// flatten returns the Terraform model of the resource in an API response.
// A value that the response does not have is null.
func flatten(ctx context.Context, v *dashboard_service.Dashboard, prior *DashboardModel) (*DashboardModel, diag.Diagnostics) {
	var diags diag.Diagnostics
	if v == nil {
		diags.AddError("Missing resource", "The API response has no Dashboard.")
		return nil, diags
	}
	out := flattenDashboard(ctx, path.Empty(), v, prior, &diags)
	if out.Id.IsNull() || out.Id.ValueString() == "" {
		diags.AddError("Missing id", "The API response has no id. Without it, Terraform cannot read, update, or delete the resource.")
	}
	return out, diags
}

