// expandSpansAggregation sends the arm that the type attribute names, with the merged fields that the arm
// holds in the API.
func expandSpansAggregation(ctx context.Context, p path.Path, m *SpansAggregationModel, diags *diag.Diagnostics) *dashboard_service.SpansAggregation {
	if m == nil {
		return nil
	}
	out := &dashboard_service.SpansAggregation{}
	kind := m.Type.ValueString()
	switch kind {
	case "dimension":
		out.DimensionAggregation = expandDimensionAggregation(ctx, p, &DimensionAggregationModel{
			AggregationType: m.AggregationType,
			DimensionField:  m.DimensionField,
		}, diags)
	case "metric":
		out.MetricAggregation = expandMetricAggregation(ctx, p, &MetricAggregationModel{
			AggregationType: m.AggregationType,
			MetricField:     m.DimensionField,
		}, diags)
	default:
		diags.AddAttributeError(p.AtName("type"), "Unknown type", fmt.Sprintf("The type %q is not one of dimension, metric.", m.Type.ValueString()))
	}
	return out
}

// flattenSpansAggregation reads the arm of SpansAggregation as the type attribute and the merged fields.
func flattenSpansAggregation(ctx context.Context, p path.Path, v *dashboard_service.SpansAggregation, diags *diag.Diagnostics) *SpansAggregationModel {
	if v == nil {
		return nil
	}
	out := &SpansAggregationModel{}
	// A field that the selected arm does not have reads as an absent value.
	if empty := flattenDimensionAggregation(ctx, p, &dashboard_service.DimensionAggregation{}, diags); empty != nil {
		out.AggregationType = empty.AggregationType
		out.DimensionField = empty.DimensionField
	}
	switch {
	case v.DimensionAggregation != nil:
		out.Type = types.StringValue("dimension")
		if arm := flattenDimensionAggregation(ctx, p, v.DimensionAggregation, diags); arm != nil {
			out.AggregationType = arm.AggregationType
			out.DimensionField = arm.DimensionField
		}
	case v.MetricAggregation != nil:
		out.Type = types.StringValue("metric")
		if arm := flattenMetricAggregation(ctx, p, v.MetricAggregation, diags); arm != nil {
			out.AggregationType = arm.AggregationType
			out.DimensionField = arm.MetricField
		}
	default:
		diags.AddAttributeError(p, "Invalid response from server", "The response has none of DimensionAggregation MetricAggregation; it must have one.")
	}
	return out
}

