	out.Min = expandFloat64(m.Min)
	out.ShowInnerArc = expandBool(m.ShowInnerArc)
	out.ShowMinMax = expandBool(m.ShowMinMax)
	out.ShowOuterArc = expandBool(m.ShowOuterArc)
